INSERT INTO data_widgets (widget_name,widget_type,widget_data,widget_style,widget_class,widget_viewport,date_updated,updated_by,short_code,div_id,bootstrap_enabled,ssl_enabled,mobile_enabled,widget_html_element,widget_javascript,file_type,widget_settings,widget_values)
SELECT 'Day 5 formfieldsA','Custom Widget','<div class="day5-form"><h2>Widget A – Name Fields</h2><div class="row"><div><label for="d5_first">First Name</label><input id="d5_first" name="first_name" type="text" placeholder="First name"></div><div><label for="d5_last">Last Name</label><input id="d5_last" name="last_name" type="text" placeholder="Last name"></div></div></div>',' .day5-form{font-family:Arial,sans-serif;color:#222;max-width:680px;margin:auto;padding:20px}.day5-form h2{margin-top:0}.day5-form label{display:block;margin:14px 0 6px;font-weight:600}.day5-form input,.day5-form select{width:100%;padding:10px;border:1px solid #cbd5e1;border-radius:7px;box-sizing:border-box}.day5-form .row{display:grid;grid-template-columns:1fr 1fr;gap:14px}.day5-form .conditional{display:none}.day5-form .conditional.visible{display:block}@media(max-width:600px){.day5-form .row{grid-template-columns:1fr}}','day5-component','front',DATE_FORMAT(NOW(),'%Y%m%d%H%i%s'),'Day 5', 'd5a00000000000000000000000000001','formfieldsA',1,1,1,'div','','html','',''
WHERE NOT EXISTS (SELECT 1 FROM data_widgets WHERE widget_name='Day 5 formfieldsA');

INSERT INTO data_widgets (widget_name,widget_type,widget_data,widget_style,widget_class,widget_viewport,date_updated,updated_by,short_code,div_id,bootstrap_enabled,ssl_enabled,mobile_enabled,widget_html_element,widget_javascript,file_type,widget_settings,widget_values)
SELECT 'Day 5 formfieldsB','Custom Widget','<div class="day5-form"><h2>Widget B – Contact Fields</h2><label for="d5_email">Email</label><input id="d5_email" name="email" type="email" placeholder="Email address"><label for="d5_phone">Phone</label><input id="d5_phone" name="phone" type="tel" placeholder="Phone number"></div>',' .day5-form{font-family:Arial,sans-serif;color:#222;max-width:680px;margin:auto;padding:20px}.day5-form h2{margin-top:0}.day5-form label{display:block;margin:14px 0 6px;font-weight:600}.day5-form input,.day5-form select{width:100%;padding:10px;border:1px solid #cbd5e1;border-radius:7px;box-sizing:border-box}.day5-form .row{display:grid;grid-template-columns:1fr 1fr;gap:14px}.day5-form .conditional{display:none}.day5-form .conditional.visible{display:block}@media(max-width:600px){.day5-form .row{grid-template-columns:1fr}}','day5-component','front',DATE_FORMAT(NOW(),'%Y%m%d%H%i%s'),'Day 5','d5b00000000000000000000000000002','formfieldsB',1,1,1,'div','','html','',''
WHERE NOT EXISTS (SELECT 1 FROM data_widgets WHERE widget_name='Day 5 formfieldsB');

INSERT INTO data_widgets (widget_name,widget_type,widget_data,widget_style,widget_class,widget_viewport,date_updated,updated_by,short_code,div_id,bootstrap_enabled,ssl_enabled,mobile_enabled,widget_html_element,widget_javascript,file_type,widget_settings,widget_values)
SELECT 'Day 5 formfieldsC','Custom Widget','<div class="day5-form"><h2>Widget C – Account Type</h2><label for="d5_account">Account Type</label><select id="d5_account" name="account_type"><option value="">Select account type</option><option value="individual">Individual</option><option value="business">Business</option></select></div>',' .day5-form{font-family:Arial,sans-serif;color:#222;max-width:680px;margin:auto;padding:20px}.day5-form h2{margin-top:0}.day5-form label{display:block;margin:14px 0 6px;font-weight:600}.day5-form input,.day5-form select{width:100%;padding:10px;border:1px solid #cbd5e1;border-radius:7px;box-sizing:border-box}.day5-form .row{display:grid;grid-template-columns:1fr 1fr;gap:14px}.day5-form .conditional{display:none}.day5-form .conditional.visible{display:block}@media(max-width:600px){.day5-form .row{grid-template-columns:1fr}}','day5-component','front',DATE_FORMAT(NOW(),'%Y%m%d%H%i%s'),'Day 5','d5c00000000000000000000000000003','formfieldsC',1,1,1,'div','','html','',''
WHERE NOT EXISTS (SELECT 1 FROM data_widgets WHERE widget_name='Day 5 formfieldsC');

INSERT INTO data_widgets (widget_name,widget_type,widget_data,widget_style,widget_class,widget_viewport,date_updated,updated_by,short_code,div_id,bootstrap_enabled,ssl_enabled,mobile_enabled,widget_html_element,widget_javascript,file_type,widget_settings,widget_values)
SELECT 'Day 5 formfieldsD','Custom Widget','<div class="day5-form"><h2>Widget D – Integrated Form</h2>[widget=formfieldsA][widget=formfieldsB][widget=formfieldsC]<div class="conditional" id="d5d_company"><label for="d5d_company_name">Company Name</label><input id="d5d_company_name" name="company_name" type="text"></div><div class="conditional" id="d5d_gst"><label for="d5d_gst_number">GST Number</label><input id="d5d_gst_number" name="gst_number" type="text"></div></div>',' .day5-form{font-family:Arial,sans-serif;color:#222;max-width:680px;margin:auto;padding:20px}.day5-form h2{margin-top:0}.day5-form label{display:block;margin:14px 0 6px;font-weight:600}.day5-form input,.day5-form select{width:100%;padding:10px;border:1px solid #cbd5e1;border-radius:7px;box-sizing:border-box}.day5-form .row{display:grid;grid-template-columns:1fr 1fr;gap:14px}.day5-form .conditional{display:none}.day5-form .conditional.visible{display:block}@media(max-width:600px){.day5-form .row{grid-template-columns:1fr}}','day5-component','front',DATE_FORMAT(NOW(),'%Y%m%d%H%i%s'),'Day 5','d5d00000000000000000000000000004','formfieldsD',1,1,1,'div','(function(){const s=document.getElementById("d5_account"),a=document.getElementById("d5d_company"),b=document.getElementById("d5d_gst");if(!s)return;function sync(){const show=s.value==="business";a.classList.toggle("visible",show);b.classList.toggle("visible",show);}s.addEventListener("change",sync);sync();})();','html','',''
WHERE NOT EXISTS (SELECT 1 FROM data_widgets WHERE widget_name='Day 5 formfieldsD');

INSERT INTO users_meta (`database`,database_id,`key`,`value`,date_added)
SELECT 'data_widgets',w.widget_id,'widget_shortcode',a.alias,DATE_FORMAT(NOW(),'%Y%m%d%H%i%s')
FROM data_widgets w JOIN (SELECT 'Day 5 formfieldsA' widget_name,'formfieldsA' alias UNION ALL SELECT 'Day 5 formfieldsB','formfieldsB' UNION ALL SELECT 'Day 5 formfieldsC','formfieldsC' UNION ALL SELECT 'Day 5 formfieldsD','formfieldsD') a ON a.widget_name=w.widget_name
WHERE NOT EXISTS (SELECT 1 FROM users_meta m WHERE m.`database`='data_widgets' AND m.database_id=w.widget_id AND m.`key`='widget_shortcode');
